::: {.cell tbl-cap='Estimation results from all models.'}

```{.r .cell-code}
list_models <- c("A_FLYw", "B_FLYe", "C_CWYe", "D_CWKe", "E_CLYe", "F_CLKe")
list_model_summary <- mget(paste0("Summary_res_", list_models))

param_order <- c(
  "pAm", "r_pAm_pM", "Fm", "rOM_ClxHorse", "K", "v", "kap", "kapJ", "kapA", "tau",
  "Ehp", "E_coc", "dv", "de", "wE", "Sigma_W"
)

format_summary <- function(df) {
  df %>%
    rename_with(~ str_remove(., "\\.1\\.$")) %>%
    rownames_to_column("stat") %>%
    pivot_longer(
      cols = -c(stat, Model),
      names_to = "param",
      values_to = "value"
    ) %>%
    pivot_wider(
      names_from = stat,
      values_from = value
    ) %>%
    mutate(
      value = str_c(
        round(Result_mode, 3),
        " [", round(`2.5%`, 3),
        " ; ", round(`97.5%`, 3), "]"
      )
    ) %>%
    dplyr::select(Model, param, value) %>%
    pivot_wider(
      names_from = param,
      values_from = value
    )
}

df_result <- list_model_summary %>%
  map(format_summary) %>%
  bind_rows() %>%
  dplyr::select(
    Model,
    any_of(param_order),
    everything()
  ) |> 
  left_join(df_LL_BIC)
```

