df_line <- data.frame(
  x1  = seq_line,
  y1  = seq_line*fact_1,
  x_1 = seq_line,
  y_1 = seq_line/fact_1,
  x2  = seq_line,
  y2  = seq_line*fact_2,
  x_2 = seq_line,
  y_2 = seq_line/fact_2
  )

p_W <- ggplot(
  data = df_predobs_Weight_A_FLYw,
  mapping = aes(
      x = Weight_obs,
      y = predict.endpoint
    )
  )+
  geom_line(
    data=df_line,
    mapping=aes(x=x1, y=y1),
    color = col_line1
    )+
  geom_line(
    data=df_line,
    mapping=aes(x=x_1, y=y_1),
    color = col_line1
